export function isStructureSearchResult(data: unknown): data is StructureSearchData {
  if (!data || typeof data !== 'object') return false
  const record = data as Record<string, unknown>
  return Array.isArray(record.results) && 'status' in record && 'query_structure' in record
}

import { useState, useRef, useEffect, type KeyboardEvent } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useShallow } from 'zustand/react/shallow'
import { useChatStore } from '@/stores/chat'
import { useChatStream } from '@/hooks/useChatStream'
import { authFetch, uploadFormWithProgress } from '@/lib/api'
import { ArrowUp, Paperclip, X, ChevronDown, Sparkles, Loader2, CheckCircle, AlertCircle } from 'lucide-react'

interface AttachedFile {
  file: File
  status: 'pending' | 'uploading' | 'done' | 'error'
  progress: number
  error?: string
  objectName?: string
  downloadUrl?: string
  analysisData?: unknown
}

const MODEL_ICONS: Record<string, typeof Sparkles> = {
  gpt55: Sparkles,
  gpt56: Sparkles,
  'gpt56-sol': Sparkles,
}

const MODEL_COLORS: Record<string, string> = {
  gpt55: 'text-amber-500 bg-amber-500/10 border-amber-500/20',
  gpt56: 'text-orange-500 bg-orange-500/10 border-orange-500/20',
  'gpt56-sol': 'text-yellow-500 bg-yellow-500/10 border-yellow-500/20',
}

export function ChatInput() {
  const { t } = useTranslation()
  const location = useLocation()
  const navigate = useNavigate()
  const [input, setInput] = useState('')
  const [files, setFiles] = useState<AttachedFile[]>([])
  const filesRef = useRef<AttachedFile[]>([])
  filesRef.current = files
  const [modelOpen, setModelOpen] = useState(false)
  const textareaRef = useRef<HTMLTextAreaElement>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const modelRef = useRef<HTMLDivElement>(null)
  const { addMessage, streaming, selectedModel, setSelectedModel, availableModels, fetchModels } = useChatStore(useShallow((s) => ({
    addMessage: s.addMessage,
    streaming: s.streaming,
    selectedModel: s.selectedModel,
    setSelectedModel: s.setSelectedModel,
    availableModels: s.availableModels,
    fetchModels: s.fetchModels,
  })))
  const { sendMessage } = useChatStream()
  const initialSent = useRef(false)

  useEffect(() => {
    if (availableModels.length === 0) {
      void fetchModels()
    }
  }, [availableModels.length, fetchModels])

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (modelRef.current && !modelRef.current.contains(e.target as Node)) setModelOpen(false)
    }
    document.addEventListener('mousedown', handleClick)
    return () => document.removeEventListener('mousedown', handleClick)
  }, [])

  // Handle initial prompt from Home page / PDB page navigation
  useEffect(() => {
    if (initialSent.current) return
    const state = location.state as { initialPrompt?: string; uploadFile?: File } | null
    if (!state?.initialPrompt && !state?.uploadFile) return

    initialSent.current = true
    const initialPrompt = state.initialPrompt
    const uploadFile = state.uploadFile
    let cancelled = false
    let timerId: number | null = null

    // Clear router state before doing any async work so reloads/remounts do not
    // replay uploads or auto-send the same prompt again.
    navigate(location.pathname, { replace: true, state: null })

    const processInitialState = async () => {
      // Case: file + prompt (from PDB page "Deep Analysis in Chat")
      if (uploadFile) {
        const attachedFile: AttachedFile = { file: uploadFile, status: 'pending', progress: 0 }
        setFiles([attachedFile])

        try {
          // Upload the file first
          const { objectName, downloadUrl } = await uploadSingleFile(attachedFile, 0)
          if (cancelled) return

          // Auto-analyze PDB files
          const ext = uploadFile.name.split('.').pop()?.toLowerCase()
          let analysisData: unknown = null
          if ((ext === 'pdb' || ext === 'ent' || ext === 'cif') && objectName) {
            analysisData = await analyzePdb(objectName)
            if (cancelled) return
          }

          const fileResult = {
            name: uploadFile.name,
            size: uploadFile.size,
            type: uploadFile.type,
            objectName,
            downloadUrl,
            analysisData,
          }

          const promptText = initialPrompt || t('chat.analyzingFiles')

          addMessage({
            role: 'user',
            content: promptText,
            files: [fileResult],
          })
          setInput('')
          updateFiles(() => [])
          sendMessage(promptText, useChatStore.getState().currentId ?? undefined, undefined, [fileResult])
        } catch {
          if (cancelled) return
          // Upload failed — fall back to text-only
          const promptText = initialPrompt || t('chat.analyzingFiles')
          addMessage({
            role: 'user',
            content: promptText,
          })
          setInput('')
          updateFiles(() => [])
          sendMessage(promptText, useChatStore.getState().currentId ?? undefined)
        }
        return
      }

      // Case: text prompt only (from Home page)
      if (initialPrompt) {
        setInput(initialPrompt)
        timerId = window.setTimeout(() => {
          if (cancelled) return
          addMessage({
            role: 'user',
            content: initialPrompt,
          })
          setInput('')
          sendMessage(initialPrompt, useChatStore.getState().currentId ?? undefined)
        }, 300)
      }
    }

    void processInitialState()

    return () => {
      cancelled = true
      if (timerId !== null) {
        window.clearTimeout(timerId)
      }
    }
  }, [location.pathname, location.state, navigate, t, addMessage, sendMessage]) // eslint-disable-line react-hooks/exhaustive-deps

  const currentModel = availableModels.find((m) => m.id === selectedModel)
  const modelLabel = currentModel?.name || 'GPT-5.5'
  const Icon = MODEL_ICONS[selectedModel] || Sparkles
  const colorClass = MODEL_COLORS[selectedModel] || MODEL_COLORS.gpt55

  const analyzePdb = async (objectName: string): Promise<unknown> => {
    const selectedModel = useChatStore.getState().selectedModel
    const resp = await authFetch('/api/pdb/analyze-by-name', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ object_name: objectName, model: selectedModel }),
    })
    if (!resp.ok) return null
    return resp.json()
  }

  // Helper: update both state and ref atomically
  const updateFiles = (updater: (prev: AttachedFile[]) => AttachedFile[]) => {
    setFiles((prev) => {
      const next = updater(prev)
      filesRef.current = next
      return next
    })
  }

  const uploadSingleFile = async (attached: AttachedFile, idx: number): Promise<{ objectName: string; downloadUrl: string }> => {
    const formData = new FormData()
    formData.append('file', attached.file)
    try {
      const data = await uploadFormWithProgress<{
        id: string
        object_name?: string
        download_url?: string
      }>('/files/upload', formData, {
        onProgress: (progress) => {
          updateFiles((prev) =>
            prev.map((f, j) => (j === idx ? { ...f, progress, status: 'uploading' } : f))
          )
        },
      })
      const objectName = data.object_name || data.id
      const downloadUrl = data.download_url || ''
      updateFiles((prev) =>
        prev.map((f, j) =>
          j === idx ? { ...f, status: 'done', progress: 100, objectName, downloadUrl } : f
        )
      )
      return { objectName, downloadUrl }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Upload failed'
      updateFiles((prev) =>
        prev.map((f, j) => (j === idx ? { ...f, status: 'error', error: message } : f))
      )
      throw error
    }
  }

  const handleSend = async () => {
    const trimmed = input.trim()
    const currentFiles = filesRef.current
    if (!trimmed && currentFiles.length === 0) return
    if (streaming) return

    // Upload pending files and collect results
    interface FileResult { name: string; size: number; type: string; objectName?: string; downloadUrl?: string; analysisData?: unknown }
    const fileResults: FileResult[] = currentFiles.map((f) => ({
      name: f.file.name,
      size: f.file.size,
      type: f.file.type,
      objectName: f.objectName,
      downloadUrl: f.downloadUrl,
      analysisData: f.analysisData,
    }))

    const pending = currentFiles.filter((f) => f.status === 'pending')
    for (let i = 0; i < currentFiles.length; i++) {
      if (currentFiles[i].status === 'pending') {
        const result = await uploadSingleFile(currentFiles[i], i)
        fileResults[i].objectName = result.objectName
        fileResults[i].downloadUrl = result.downloadUrl
        // Auto-analyze PDB files after upload
        const ext = currentFiles[i].file.name.split('.').pop()?.toLowerCase()
        if ((ext === 'pdb' || ext === 'ent' || ext === 'cif') && result.objectName) {
          fileResults[i].analysisData = await analyzePdb(result.objectName)
        }
      }
    }

    addMessage({
      role: 'user',
      content: trimmed || t('chat.analyzingFiles'),
      files: fileResults,
    })
    setInput('')
    updateFiles(() => [])
    if (textareaRef.current) textareaRef.current.style.height = 'auto'
    sendMessage(trimmed || t('chat.analyzingFiles'), useChatStore.getState().currentId ?? undefined, undefined, fileResults)
  }

  const handleKeyDown = (e: KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend() }
  }

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles: AttachedFile[] = Array.from(e.target.files).map((f) => ({
        file: f,
        status: 'pending' as const,
        progress: 0,
      }))
      updateFiles((prev) => [...prev, ...newFiles])
    }
  }

  return (
    <div className="border-t border-border/70 bg-background/65 px-3 py-3 backdrop-blur sm:px-4 sm:py-4">
      <div className="mx-auto max-w-4xl">
        {/* File previews */}
        {files.length > 0 && (
          <div className="mb-3 flex flex-wrap gap-2">
            {files.map((file, i) => (
              <div key={i} className="flex items-center gap-2 rounded-2xl border border-border/80 bg-card/90 px-3 py-2 text-xs shadow-sm">
                {file.status === 'uploading' ? (
                  <Loader2 className="w-3 h-3 animate-spin text-muted-foreground" />
                ) : file.status === 'done' ? (
                  <CheckCircle className="w-3 h-3 text-green-500" />
                ) : file.status === 'error' ? (
                  <AlertCircle className="w-3 h-3 text-red-500" />
                ) : (
                  <Paperclip className="w-3 h-3 text-muted-foreground" />
                )}
                <span className="max-w-[120px] truncate">{file.file.name}</span>
                {file.status === 'uploading' && (
                  <span className="text-[10px] text-muted-foreground">{file.progress}%</span>
                )}
                <button onClick={() => updateFiles((p) => p.filter((_, j) => j !== i))} className="text-muted-foreground hover:text-foreground">
                  <X className="w-3 h-3" />
                </button>
              </div>
            ))}
          </div>
        )}

        {/* Input area */}
        <div className="rounded-[28px] border border-border/80 bg-card/90 p-3 shadow-[0_20px_60px_rgba(15,23,42,0.08)] backdrop-blur">
          <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
            <div ref={modelRef} className="relative z-20">
              <button
                onClick={() => setModelOpen(!modelOpen)}
                className={`flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs font-medium transition-all hover:opacity-80 active:scale-[0.97] ${colorClass}`}
              >
                <Icon className="w-3 h-3" />
                <span>{modelLabel}</span>
                <ChevronDown className={`w-3 h-3 transition-transform duration-200 ${modelOpen ? 'rotate-180' : ''}`} />
              </button>
              {modelOpen && (
                <div className="absolute bottom-full left-0 z-[120] mb-2 w-72 overflow-hidden rounded-2xl border border-border bg-popover py-1.5 text-popover-foreground shadow-2xl ring-1 ring-black/5 backdrop-blur-sm">
                  <div className="px-3 py-1.5 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">
                    {t('chat.selectModel')}
                  </div>
                  {availableModels.map((m) => {
                    const MI = MODEL_ICONS[m.id] || Sparkles
                    const MC = MODEL_COLORS[m.id] || ''
                    return (
                      <button
                        key={m.id}
                        onClick={() => { setSelectedModel(m.id); setModelOpen(false) }}
                        disabled={!m.available}
                        className={`flex w-full items-center gap-2.5 px-3 py-2.5 text-left text-xs transition-colors
                          ${m.id === selectedModel ? 'bg-secondary font-medium' : 'hover:bg-secondary/70'}
                          ${!m.available ? 'cursor-not-allowed opacity-40' : ''}`}
                      >
                        <span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-md border ${MC}`}>
                          <MI className="w-3 h-3" />
                        </span>
                        <span className="min-w-0 flex-1">
                          <span className="block truncate">{m.name}</span>
                          <span className="block truncate text-[10px] text-muted-foreground">{m.description}</span>
                        </span>
                        {m.id === selectedModel && (
                          <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-primary" />
                        )}
                      </button>
                    )
                  })}
                </div>
              )}
            </div>
            <div className="rounded-full border border-border/80 bg-background/80 px-3 py-1 text-[11px] text-muted-foreground">
              {streaming ? 'Streaming response...' : t('chat.hint')}
            </div>
          </div>

          <div className="flex items-end gap-3 rounded-[24px] border border-border/80 bg-background/80 px-4 py-3 transition-colors focus-within:border-ring">
            <button
              onClick={() => fileInputRef.current?.click()}
              className="mb-0.5 shrink-0 rounded-2xl border border-border/80 bg-card p-2 text-muted-foreground transition-colors hover:bg-secondary"
            >
              <Paperclip className="w-4 h-4" />
            </button>
            <input
              ref={fileInputRef}
              type="file"
              multiple
              onChange={handleFileSelect}
              className="hidden"
              accept=".pdb,.fasta,.cif,.sdf,.txt,.csv,.json"
            />

            <textarea
              ref={textareaRef}
              value={input}
              onChange={(e) => {
                setInput(e.target.value)
                const el = e.target
                el.style.height = 'auto'
                el.style.height = Math.min(el.scrollHeight, 200) + 'px'
              }}
              onKeyDown={handleKeyDown}
              placeholder={t('chat.placeholder')}
              rows={1}
              className="flex-1 resize-none bg-transparent text-sm leading-7 placeholder:text-muted-foreground focus:outline-none"
            />

            <button
              onClick={handleSend}
              disabled={!input.trim() && files.length === 0}
              className="mb-0.5 shrink-0 rounded-2xl bg-primary p-2.5 text-primary-foreground shadow-[0_12px_28px_rgba(37,99,235,0.26)] transition-colors hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-30"
            >
              <ArrowUp className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

import { memo } from 'react'
import type { ChatMessage } from '@/stores/chat'
import { MarkdownView } from '@/components/chat/MarkdownView'
import { ToolCallCard } from '@/components/chat/ToolCallCard'
import { PDBAnalysisCard, isPDBAnalysisResult, type PDBAnalysisData } from '@/components/analysis/PDBAnalysisCard'
import { ReportBody, ReportShell } from '@/components/analysis/ReportShell'
import { PublishToolbar } from '@/components/chat/PublishToolbar'

interface Props {
  message: ChatMessage
  conversationId?: string | null
  projectId?: string | null
  isStreaming?: boolean
}

function looksLikeStructuredReport(content: string) {
  const text = content.trim()
  if (text.length < 180) return false
  return (
    /(^|\n)(执行摘要|摘要|结论|建议|总结|AI Summary|##\s|###\s)/m.test(text) ||
    /\|[^|\n]+\|[^|\n]+\|/.test(text) ||
    /(^|\s)\d+\.\s+\S+/m.test(text) ||
    /(报告|分析|改造方案|实验验证|突变优先级)/.test(text)
  )
}

function MessageBubbleBase({ message, conversationId, projectId, isStreaming = false }: Props) {
  const isUser = message.role === 'user'
  const isSystem = message.role === 'system'
  const isAssistant = !isUser && !isSystem

  const pdbAnalysis: PDBAnalysisData | undefined = message.files?.find((f) => isPDBAnalysisResult(f.analysisData))?.analysisData as PDBAnalysisData | undefined
  // Avoid switching the outer message container mid-stream, which causes a
  // visible relayout once long reports cross the structured-report threshold.
  const shouldUseReportShell =
    isAssistant && !isStreaming && !!message.content && looksLikeStructuredReport(message.content)

  return (
    <div className="flex">
      {/* Avatar */}
      {isSystem && (
        <div
          className="mt-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl border border-orange-500/20 bg-orange-500/10 text-orange-500 shadow-sm"
        >
          <span className="text-xs font-bold">S</span>
        </div>
      )}

      {/* Content */}
      <div className={`min-w-0 ${isUser ? 'w-full' : 'w-full'}`}>
        {/* Message body */}
        <div
          className={`w-full text-sm ${
            isUser
              ? 'mx-auto max-w-[860px] rounded-[24px] border border-border/70 bg-secondary/30 px-4 py-3.5 text-foreground/78 shadow-[0_8px_28px_rgba(15,23,42,0.04)]'
              : isSystem
                ? 'rounded-[24px] border border-orange-500/20 bg-orange-500/5 px-5 py-4'
                : 'px-0 py-1'
          }`}
        >
          {message.toolCalls && message.toolCalls.length > 0 && (
            <div className={`mb-5 space-y-2 ${isAssistant ? 'mx-auto max-w-[860px]' : ''}`}>
              {message.toolCalls.map((tc) => (
                <ToolCallCard key={tc.id} toolCall={tc} />
              ))}
            </div>
          )}
          {pdbAnalysis && isUser && (
            <div className="mb-3">
              <PDBAnalysisCard data={pdbAnalysis} />
            </div>
          )}
          {message.content ? (
            <div className={isAssistant ? 'mx-auto max-w-[900px]' : ''}>
              {shouldUseReportShell ? (
                <ReportShell>
                  <ReportBody className="space-y-0">
                    <MarkdownView content={message.content} streaming={isStreaming} />
                  </ReportBody>
                </ReportShell>
              ) : (
                <MarkdownView content={message.content} streaming={isStreaming} compact={isUser} />
              )}
            </div>
          ) : (!message.toolCalls || message.toolCalls.length === 0) ? (
            <span className="text-muted-foreground italic text-xs">Thinking...</span>
          ) : null}
        </div>

        {/* Publish toolbar — only on assistant messages with content */}
        {!isUser && !isSystem && message.content && (
          <PublishToolbar
            content={message.content}
            conversationId={conversationId ? Number(conversationId) : undefined}
          />
        )}
      </div>
    </div>
  )
}

export const MessageBubble = memo(
  MessageBubbleBase,
  (prev, next) =>
    prev.message === next.message &&
    prev.conversationId === next.conversationId &&
    prev.projectId === next.projectId &&
    prev.isStreaming === next.isStreaming
)

import { useState, useCallback, useEffect, useMemo } from 'react'
import { FileText, Pencil, Check, X, Loader2, BookOpen, ChevronRight, FolderTree } from 'lucide-react'
import { api } from '@/lib/api'

interface Props {
  content: string
  conversationId?: number
}

interface WikiCollectionOption {
  id: string
  name: string
  description?: string | null
  document_count?: number | null
}

interface WikiDocument {
  id: string
  title: string
  parent_id: string | null
  url_id: string | null
  updated_at: string | null
  emoji: string | null
}

interface WikiTreeResponse {
  collection_id: string | null
  root_doc_id: string | null
  documents: WikiDocument[]
}

interface WikiTreeNode extends WikiDocument {
  children: WikiTreeNode[]
}

const COLLECTION_ROOT = '__collection_root__'

function buildWikiTree(documents: WikiDocument[]): WikiTreeNode[] {
  const nodeMap = new Map<string, WikiTreeNode>()
  for (const doc of documents) {
    nodeMap.set(doc.id, { ...doc, children: [] })
  }

  const topLevel: WikiTreeNode[] = []
  for (const doc of documents) {
    const node = nodeMap.get(doc.id)
    if (!node) continue

    if (doc.parent_id && nodeMap.has(doc.parent_id)) {
      nodeMap.get(doc.parent_id)!.children.push(node)
      continue
    }
    topLevel.push(node)
  }

  const sortNodes = (nodes: WikiTreeNode[]) => {
    nodes.sort((a, b) => a.title.localeCompare(b.title, 'zh-CN'))
    nodes.forEach((node) => sortNodes(node.children))
  }
  sortNodes(topLevel)
  return topLevel
}

export function PublishToolbar({ content, conversationId }: Props) {
  const [showEditor, setShowEditor] = useState(false)
  const [editContent, setEditContent] = useState('')
  const [title, setTitle] = useState('')
  const [publishing, setPublishing] = useState(false)
  const [published, setPublished] = useState(false)
  const [error, setError] = useState('')
  const [collections, setCollections] = useState<WikiCollectionOption[]>([])
  const [collectionsLoading, setCollectionsLoading] = useState(false)
  const [selectedCollectionId, setSelectedCollectionId] = useState('')
  const [wikiTreeData, setWikiTreeData] = useState<WikiTreeResponse | null>(null)
  const [wikiTreeLoading, setWikiTreeLoading] = useState(false)
  const [selectedTargetId, setSelectedTargetId] = useState<string>('')

  const openEditor = useCallback(() => {
    setEditContent(content)
    setTitle(`分析报告 ${new Date().toLocaleDateString('zh-CN')}`)
    setShowEditor(true)
    setError('')
    setPublished(false)
    setWikiTreeData(null)
    setSelectedTargetId('')
    setSelectedCollectionId('')
  }, [content])

  useEffect(() => {
    if (!showEditor) return
    if (collections.length > 0) return

    let active = true
    setCollectionsLoading(true)
    void api.getWikiCollections()
      .then((data) => {
        if (!active) return
        setCollections(data)
        if (data.length === 1) {
          setSelectedCollectionId(data[0].id)
        }
      })
      .catch((e: any) => {
        if (!active) return
        setError(e?.message || '加载 Wiki collection 失败')
      })
      .finally(() => {
        if (active) setCollectionsLoading(false)
      })

    return () => {
      active = false
    }
  }, [showEditor, collections.length])

  useEffect(() => {
    if (!showEditor || !selectedCollectionId) {
      setWikiTreeData(null)
      setSelectedTargetId('')
      return
    }

    let active = true
    setWikiTreeLoading(true)
    setError('')

    void api.getCollectionTree(selectedCollectionId)
      .then((data) => {
        if (!active) return
        setWikiTreeData(data)
        setSelectedTargetId(COLLECTION_ROOT)
      })
      .catch((e: any) => {
        if (!active) return
        setWikiTreeData(null)
        setSelectedTargetId(COLLECTION_ROOT)
        setError(e?.message || '加载知识库目录树失败')
      })
      .finally(() => {
        if (active) setWikiTreeLoading(false)
      })

    return () => {
      active = false
    }
  }, [showEditor, selectedCollectionId])

  const treeNodes = useMemo(
    () => buildWikiTree(wikiTreeData?.documents || []),
    [wikiTreeData]
  )

  const renderTreeNode = useCallback((node: WikiTreeNode, depth = 0) => {
    const selected = selectedTargetId === node.id
    return (
      <div key={node.id}>
        <button
          type="button"
          onClick={() => setSelectedTargetId(node.id)}
          className={`flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm transition-colors ${
            selected ? 'bg-primary/10 text-foreground ring-1 ring-primary/30' : 'hover:bg-muted'
          }`}
          style={{ paddingLeft: `${depth * 16 + 8}px` }}
        >
          <ChevronRight className={`h-3.5 w-3.5 shrink-0 text-muted-foreground ${node.children.length ? '' : 'opacity-30'}`} />
          <span className="truncate">
            {node.emoji ? `${node.emoji} ` : ''}
            {node.title}
          </span>
        </button>
        {node.children.length > 0 && (
          <div>
            {node.children.map((child) => renderTreeNode(child, depth + 1))}
          </div>
        )}
      </div>
    )
  }, [selectedTargetId])

  const handlePublish = useCallback(async () => {
    if (!selectedCollectionId) {
      setError('请选择 Wiki collection')
      return
    }
    if (!selectedTargetId) {
      setError('请选择知识库目录节点')
      return
    }
    setPublishing(true)
    setError('')
    try {
      await api.publishToWikiCollection({
        title,
        content: editContent,
        conversation_id: conversationId,
        collection_id: selectedCollectionId,
        parent_document_id: selectedTargetId === COLLECTION_ROOT ? undefined : selectedTargetId,
      })
      setPublished(true)
      setShowEditor(false)
    } catch (e: any) {
      setError(e.message || '发布失败')
    } finally {
      setPublishing(false)
    }
  }, [selectedCollectionId, selectedTargetId, title, editContent, conversationId])

  // Don't show for very short messages (likely not full reports)
  if (!content || content.length < 100) return null
  // Don't show if already published
  if (published) {
    return (
      <div className="mx-auto mt-4 flex max-w-[860px] items-center gap-2 text-xs text-green-600">
        <Check className="w-3.5 h-3.5" />
        <span>已发布到Wiki知识库</span>
      </div>
    )
  }

  return (
    <>
      {/* Toolbar buttons */}
      <div className="mx-auto mt-5 flex max-w-[860px] items-center gap-3">
        <button
          onClick={openEditor}
          className="inline-flex items-center gap-1.5 rounded-full border border-border/80 px-3 py-1.5 text-xs
                     bg-background/80 text-muted-foreground hover:bg-muted/60 hover:text-foreground
                     transition-colors"
          title="编辑并发布到Wiki"
        >
          <Pencil className="w-3 h-3" />
          发布到Wiki
        </button>
      </div>

      {/* Editor Modal */}
      {showEditor && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
             onClick={() => setShowEditor(false)}>
          <div className="bg-card border border-border rounded-xl shadow-2xl w-[90vw] max-w-4xl max-h-[85vh] flex flex-col"
               onClick={e => e.stopPropagation()}>
            {/* Header */}
            <div className="flex items-center justify-between px-5 py-3 border-b border-border">
              <div className="flex items-center gap-2">
                <BookOpen className="w-4 h-4 text-primary" />
                <h3 className="font-medium text-sm">编辑并发布到Wiki知识库</h3>
              </div>
              <button onClick={() => setShowEditor(false)}
                      className="p-1 rounded hover:bg-muted">
                <X className="w-4 h-4" />
              </button>
            </div>

            {/* Title input */}
            <div className="px-5 py-2 border-b border-border">
              <div className="mb-2 flex items-center gap-2">
                <BookOpen className="w-3.5 h-3.5 text-primary" />
                <span className="text-xs font-medium text-muted-foreground">Wiki Collection</span>
              </div>
              <select
                value={selectedCollectionId}
                onChange={(e) => setSelectedCollectionId(e.target.value)}
                className="mb-3 w-full px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary/30"
                disabled={collectionsLoading || publishing}
              >
                <option value="">
                  {collectionsLoading ? '正在加载 Wiki collections...' : '请选择已存在的 Wiki collection'}
                </option>
                {collections.map((collection) => (
                  <option key={collection.id} value={collection.id}>
                    {collection.name}
                    {typeof collection.document_count === 'number' ? ` (${collection.document_count})` : ''}
                  </option>
                ))}
              </select>
              <input
                type="text"
                value={title}
                onChange={e => setTitle(e.target.value)}
                placeholder="报告标题"
                className="w-full px-3 py-1.5 text-sm bg-background border border-border rounded-md
                           focus:outline-none focus:ring-2 focus:ring-primary/30"
              />
            </div>

            <div className="px-5 py-3 border-b border-border">
              <div className="mb-2 flex items-center gap-2">
                <FolderTree className="w-3.5 h-3.5 text-primary" />
                <span className="text-xs font-medium text-muted-foreground">选择知识库目录</span>
              </div>
              <div className="max-h-52 overflow-y-auto rounded-lg border border-border bg-background p-2">
                {!selectedCollectionId ? (
                  <div className="px-2 py-3 text-sm text-muted-foreground">请先选择 Wiki collection</div>
                ) : wikiTreeLoading ? (
                  <div className="flex items-center gap-2 px-2 py-3 text-sm text-muted-foreground">
                    <Loader2 className="h-4 w-4 animate-spin" />
                    正在加载目录树...
                  </div>
                ) : (
                  <>
                    <button
                      type="button"
                      onClick={() => setSelectedTargetId(COLLECTION_ROOT)}
                      className={`mb-1 flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm transition-colors ${
                        selectedTargetId === COLLECTION_ROOT
                          ? 'bg-primary/10 text-foreground ring-1 ring-primary/30'
                          : 'hover:bg-muted'
                      }`}
                    >
                      <BookOpen className="h-3.5 w-3.5 text-muted-foreground" />
                      <span>知识库根目录</span>
                    </button>
                    {treeNodes.length > 0 ? (
                      treeNodes.map((node) => renderTreeNode(node))
                    ) : (
                      <div className="px-2 py-3 text-sm text-muted-foreground">
                        当前知识库还没有目录文档，将发布到根目录。
                      </div>
                    )}
                  </>
                )}
              </div>
              <div className="mt-2 text-xs text-muted-foreground">
                选中节点后，新报告会作为该节点下的新文档发布。
              </div>
            </div>

            {/* Markdown Editor */}
            <div className="flex-1 min-h-0 p-5 overflow-hidden">
              <textarea
                value={editContent}
                onChange={e => setEditContent(e.target.value)}
                className="w-full h-full min-h-[400px] p-4 text-sm font-mono leading-relaxed
                           bg-background border border-border rounded-lg resize-none
                           focus:outline-none focus:ring-2 focus:ring-primary/30"
                spellCheck={false}
              />
            </div>

            {/* Footer */}
            <div className="flex items-center justify-between px-5 py-3 border-t border-border">
              <div className="text-xs text-muted-foreground">
                {editContent.length} 字符 · Markdown 格式
                {error && <span className="text-red-500 ml-2">{error}</span>}
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setShowEditor(false)}
                  className="px-3 py-1.5 text-sm rounded-md border border-border hover:bg-muted transition-colors"
                >
                  取消
                </button>
                <button
                  onClick={handlePublish}
                  disabled={publishing || !title.trim() || !editContent.trim() || !selectedCollectionId || !selectedTargetId}
                  className="inline-flex items-center gap-1.5 px-4 py-1.5 text-sm rounded-md
                             bg-primary text-primary-foreground hover:bg-primary/90
                             disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  {publishing ? (
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                  ) : (
                    <FileText className="w-3.5 h-3.5" />
                  )}
                  发布到Wiki
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

