import { useEffect, useRef, useState } from 'react'
import { useTranslation } from 'react-i18next'
import { Search, MessageSquare } from 'lucide-react'
import { useChatStore } from '@/stores/chat'

interface Props {
  open: boolean
  onClose: () => void
}

export function SearchDialog({ open, onClose }: Props) {
  const { t } = useTranslation()
  const conversations = useChatStore((s) => s.conversations)
  const selectConversation = useChatStore((s) => s.selectConversation)
  const inputRef = useRef<HTMLInputElement>(null)
  const [query, setQuery] = useState('')

  // Focus input and reset query when opened
  useEffect(() => {
    if (open) {
      setQuery('')
      // Small delay to ensure the input is rendered
      requestAnimationFrame(() => inputRef.current?.focus())
    }
  }, [open])

  // Close on Escape (handled by keydown)
  useEffect(() => {
    if (!open) return
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose()
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [open, onClose])

  const filtered = query.trim()
    ? conversations.filter((c) =>
        c.title.toLowerCase().includes(query.toLowerCase())
      )
    : conversations.slice(0, 5)

  const handleSelect = (id: string) => {
    selectConversation(id)
    onClose()
  }

  if (!open) return null

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-[15vh]">
      {/* Backdrop */}
      <div className="fixed inset-0 bg-black/50" onClick={onClose} />

      <div className="relative bg-card border border-border rounded-xl shadow-2xl w-full max-w-lg overflow-hidden">
        {/* Search input */}
        <div className="flex items-center gap-2 px-4 py-3 border-b border-border">
          <Search className="w-4 h-4 text-muted-foreground shrink-0" />
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={t('search.placeholder')}
            className="flex-1 bg-transparent text-sm focus:outline-none"
          />
          <kbd className="text-[10px] px-1.5 py-0.5 rounded bg-secondary text-muted-foreground font-mono shrink-0">
            ESC
          </kbd>
        </div>

        {/* Results */}
        {filtered.length > 0 ? (
          <div className="max-h-64 overflow-y-auto">
            {!query.trim() && (
              <div className="px-4 py-2 text-[11px] font-medium text-muted-foreground uppercase tracking-wider">
                {t('search.recentConversations')}
              </div>
            )}
            {filtered.map((conv) => (
              <button
                key={conv.id}
                onClick={() => handleSelect(conv.id)}
                className="w-full flex items-center gap-3 px-4 py-2.5 text-sm hover:bg-secondary transition-colors text-left"
              >
                <MessageSquare className="w-4 h-4 text-muted-foreground shrink-0" />
                <span className="truncate">{conv.title}</span>
              </button>
            ))}
          </div>
        ) : query.trim() ? (
          <div className="p-6 text-center">
            <p className="text-sm text-muted-foreground">
              {t('search.noResults')}
            </p>
          </div>
        ) : (
          <div className="p-4 text-xs text-muted-foreground text-center">
            {t('search.hint')}
          </div>
        )}
      </div>
    </div>
  )
}

import { useEffect, useRef, useState, useCallback } from 'react'
import { Loader2, Maximize2, Minimize2, RotateCcw } from 'lucide-react'

type StyleMode = 'cartoon' | 'stick' | 'sphere' | 'surface' | 'ribbon'

const STYLE_OPTIONS: { mode: StyleMode; label: string }[] = [
  { mode: 'cartoon', label: 'Cartoon' },
  { mode: 'stick', label: 'Stick' },
  { mode: 'sphere', label: 'Sphere' },
  { mode: 'surface', label: 'Surface' },
  { mode: 'ribbon', label: 'Ribbon' },
]

interface Props {
  pdbData: string
  className?: string
  height?: number
  highlightResidues?: Array<{
    chainId?: string | null
    residueNumber: number
    color?: string
  }>
  highlightRanges?: Array<{
    chainId?: string | null
    startResidue: number
    endResidue: number
    color?: string
  }>
}

export function ProteinViewer({ pdbData, className = '', height = 350, highlightResidues = [], highlightRanges = [] }: Props) {
  const rootRef = useRef<HTMLDivElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const viewerRef = useRef<$3Dmol.GLViewer | null>(null)
  const viewerModuleReadyRef = useRef(false)
  const resizeFrameRef = useRef<number | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [mode, setMode] = useState<StyleMode>('cartoon')
  const [isFullscreen, setIsFullscreen] = useState(false)

  const hasRenderableSize = useCallback((el: HTMLDivElement | null) => {
    if (!el) return false
    if (!el.isConnected || document.visibilityState === 'hidden') return false
    const rect = el.getBoundingClientRect()
    const style = window.getComputedStyle(el)
    return (
      rect.width >= 24 &&
      rect.height >= 24 &&
      el.getClientRects().length > 0 &&
      style.display !== 'none' &&
      style.visibility !== 'hidden'
    )
  }, [])

  const safeRender = useCallback((viewer: $3Dmol.GLViewer) => {
    const el = containerRef.current
    if (!hasRenderableSize(el)) return false
    try {
      viewer.resize()
      viewer.render()
      return true
    } catch {
      return false
    }
  }, [hasRenderableSize])

  const destroyViewer = useCallback(() => {
    if (viewerRef.current) {
      try { viewerRef.current.clear() } catch { /* ignore */ }
      viewerRef.current = null
    }
  }, [])

  const applyHighlights = useCallback((v: $3Dmol.GLViewer) => {
    const viewerWithAddStyle = v as $3Dmol.GLViewer & {
      addStyle: (selection: Record<string, string | number>, style: Record<string, unknown>) => void
    }

    for (const highlight of highlightRanges) {
      const selection: Record<string, string | number> = {
        resi: `${highlight.startResidue}-${highlight.endResidue}`,
      }
      if (highlight.chainId) {
        selection.chain = highlight.chainId
      }

      viewerWithAddStyle.addStyle(selection, {
        cartoon: {
          color: highlight.color || '#0ea5e9',
          opacity: 0.95,
        },
      })
    }

    for (const highlight of highlightResidues) {
      const selection: Record<string, string | number> = { resi: highlight.residueNumber }
      if (highlight.chainId) {
        selection.chain = highlight.chainId
      }

      viewerWithAddStyle.addStyle(selection, {
        stick: {
          color: highlight.color || '#ef4444',
          radius: 0.28,
        },
        sphere: {
          color: highlight.color || '#ef4444',
          scale: 0.38,
        },
      })
    }
  }, [highlightRanges, highlightResidues])

  const applyStyle = useCallback((v: $3Dmol.GLViewer, styleMode: StyleMode) => {
    v.clear()
    v.addModel(pdbData, 'pdb')

    switch (styleMode) {
      case 'cartoon':
        v.setStyle({}, { cartoon: { color: 'spectrum' } })
        break
      case 'stick':
        v.setStyle({}, { stick: { color: 'spectrum', radius: 0.15 } })
        break
      case 'sphere':
        v.setStyle({}, { sphere: { color: 'spectrum', scale: 0.3 } })
        break
      case 'surface':
        v.setStyle({}, { cartoon: { color: 'spectrum', opacity: 0.5 } })
        v.addSurface($3Dmol.SurfaceType.VDW, { color: 'spectrum', opacity: 0.7 })
        break
      case 'ribbon':
        v.setStyle({}, { cartoon: { style: 'ribbon', color: 'spectrum' } })
        break
    }
    applyHighlights(v)
    v.zoomTo()
  }, [applyHighlights, pdbData])

  const initializeViewer = useCallback((styleMode: StyleMode) => {
    const el = containerRef.current
    if (!viewerModuleReadyRef.current || !hasRenderableSize(el) || !el) {
      return false
    }

    try {
      destroyViewer()
      const viewer = $3Dmol.createViewer(el, {
        backgroundColor: '0xf8fafc',
        antialias: true,
      })
      viewerRef.current = viewer
      applyStyle(viewer, styleMode)
      if (!safeRender(viewer)) {
        destroyViewer()
        return false
      }
      setLoading(false)
      setError(null)
      return true
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to render structure')
      setLoading(false)
      return false
    }
  }, [applyStyle, destroyViewer, hasRenderableSize])

  useEffect(() => {
    if (!containerRef.current || !pdbData) return

    let disposed = false
    setLoading(true)
    setError(null)
    destroyViewer()

    // Load 3Dmol dynamically
    import('3dmol/build/3Dmol.js').then(() => {
      if (disposed) return
      viewerModuleReadyRef.current = true
      initializeViewer(mode)
    }).catch(() => {
      if (!disposed) {
        setError('Failed to load 3D viewer')
        setLoading(false)
      }
    })

    return () => {
      disposed = true
      destroyViewer()
    }
  }, [destroyViewer, initializeViewer, pdbData])

  // Handle style mode changes
  useEffect(() => {
    if (viewerRef.current && !loading) {
      applyStyle(viewerRef.current, mode)
      if (!safeRender(viewerRef.current)) {
        destroyViewer()
        setLoading(true)
      }
      return
    }

    if (viewerModuleReadyRef.current && !viewerRef.current) {
      initializeViewer(mode)
    }
  }, [applyStyle, initializeViewer, loading, mode])

  // Handle resize
  useEffect(() => {
    const el = containerRef.current
    if (!el) return
    const ro = new ResizeObserver(() => {
      if (resizeFrameRef.current !== null) {
        cancelAnimationFrame(resizeFrameRef.current)
      }
      resizeFrameRef.current = requestAnimationFrame(() => {
        resizeFrameRef.current = null
        if (!hasRenderableSize(el)) {
          destroyViewer()
          setLoading(true)
          return
        }
        if (viewerRef.current) {
          if (!safeRender(viewerRef.current)) {
            destroyViewer()
            setLoading(true)
          }
          return
        }
        if (viewerModuleReadyRef.current && pdbData) {
          initializeViewer(mode)
        }
      })
    })
    ro.observe(el)
    return () => {
      ro.disconnect()
      if (resizeFrameRef.current !== null) {
        cancelAnimationFrame(resizeFrameRef.current)
        resizeFrameRef.current = null
      }
    }
  }, [destroyViewer, hasRenderableSize, initializeViewer, mode, pdbData, safeRender])

  const handleReset = () => {
    if (viewerRef.current) {
      applyStyle(viewerRef.current, mode)
    }
  }

  const syncFullscreenState = useCallback(() => {
    const fullscreenElement = document.fullscreenElement
    setIsFullscreen(Boolean(rootRef.current && fullscreenElement === rootRef.current))
  }, [])

  useEffect(() => {
    const handleFullscreenChange = () => {
      syncFullscreenState()
      requestAnimationFrame(() => {
        if (viewerRef.current) {
          safeRender(viewerRef.current)
        } else if (viewerModuleReadyRef.current && pdbData) {
          initializeViewer(mode)
        }
      })
    }

    document.addEventListener('fullscreenchange', handleFullscreenChange)
    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange)
    }
  }, [initializeViewer, mode, pdbData, safeRender, syncFullscreenState])

  const toggleFullscreen = useCallback(async () => {
    const root = rootRef.current
    if (!root) return

    try {
      if (document.fullscreenElement === root) {
        await document.exitFullscreen()
        return
      }

      if (!document.fullscreenElement) {
        await root.requestFullscreen()
      }
    } catch {
      setError('Failed to toggle fullscreen view')
    }
  }, [])

  if (error) {
    return (
      <div className={`bg-red-500/5 border border-red-500/20 rounded-lg p-6 text-center ${className}`}>
        <p className="text-sm text-red-400">{error}</p>
      </div>
    )
  }

  return (
    <div
      ref={rootRef}
      className={`border border-border rounded-xl overflow-hidden bg-card ${isFullscreen ? 'h-screen w-screen rounded-none border-0' : ''} ${className}`}
    >
      {/* Toolbar */}
      <div className="flex items-center gap-1 px-2 py-1.5 bg-secondary/50 border-b border-border">
        <div className="flex items-center gap-0.5">
          {STYLE_OPTIONS.map((opt) => (
            <button
              key={opt.mode}
              onClick={() => setMode(opt.mode)}
              className={`px-2 py-0.5 rounded text-[10px] font-medium transition-colors ${
                mode === opt.mode
                  ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:text-foreground hover:bg-secondary'
              }`}
            >
              {opt.label}
            </button>
          ))}
        </div>
        <div className="flex-1" />
        <button
          onClick={handleReset}
          className="p-1 rounded hover:bg-secondary text-muted-foreground"
          title="Reset view"
        >
          <RotateCcw className="w-3 h-3" />
        </button>
        <button
          onClick={() => { void toggleFullscreen() }}
          className="p-1 rounded hover:bg-secondary text-muted-foreground"
          title={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
        >
          {isFullscreen ? <Minimize2 className="w-3 h-3" /> : <Maximize2 className="w-3 h-3" />}
        </button>
      </div>

      {/* Canvas */}
      <div className="relative" style={{ height: isFullscreen ? 'calc(100vh - 45px)' : height }}>
        {loading && (
          <div className="absolute inset-0 flex items-center justify-center bg-background/80 z-10">
            <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
          </div>
        )}
        <div
          ref={containerRef}
          className="w-full h-full relative"
          style={{ minHeight: height }}
        />
      </div>
    </div>
  )
}

import { useShallow } from 'zustand/react/shallow'
import { useChatStore, AgentState, ToolCall } from '@/stores/chat'
import { useAuthStore } from '@/stores/auth'
import { authFetch, isUnauthorizedError } from '@/lib/api'

export function useChatStream() {
  const { addMessage, updateLastAssistant, addToolCall, updateToolCall, setStreaming, setAgentState, upsertConversationSnapshot } =
    useChatStore(useShallow((s) => ({
      addMessage: s.addMessage,
      updateLastAssistant: s.updateLastAssistant,
      addToolCall: s.addToolCall,
      updateToolCall: s.updateToolCall,
      setStreaming: s.setStreaming,
      setAgentState: s.setAgentState,
      upsertConversationSnapshot: s.upsertConversationSnapshot,
    })))

  const sendMessage = async (content: string, conversationId?: string, projectId?: string, files?: Array<{name?: string; objectName?: string; downloadUrl?: string; analysisData?: unknown}>) => {
    const initialConversationId = conversationId ?? useChatStore.getState().currentId ?? undefined
    setStreaming(true)
    let streamFinished = false

    // Add placeholder assistant message
    addMessage({
      role: 'assistant',
      content: '',
      toolCalls: [],
      thinking: [],
    })

    try {
      // Build history from last 10 messages (role + content only)
      const store = useChatStore.getState()
      const history: { role: string; content: string }[] = store.messages
        .slice(-11, -1) // exclude the placeholder assistant message we just added
        .slice(-10)
        .filter((m) => m.role === 'user' || m.role === 'assistant')
        .map((m) => ({ role: m.role, content: m.content }))

      const selectedModel = useChatStore.getState().selectedModel

      const response = await authFetch('/api/chat/stream', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: files && files.length > 0
            ? content + '\n\n[Attached files:\n' + files.map(f => {
                const parts = []
                if (f.name) parts.push('name: ' + f.name)
                if (f.objectName) parts.push('object_name: ' + f.objectName)
                if (f.downloadUrl) parts.push('download_url: ' + f.downloadUrl)
                if (f.analysisData) parts.push('analysis: ' + JSON.stringify(f.analysisData))
                return '- ' + parts.join(', ')
              }).join('\n') + ']'
            : content,
          conversation_id: conversationId || null,
          project_id: projectId || null,
          history,
          model: selectedModel,
        }),
      })

      if (response.status === 401) {
        useAuthStore.getState().logout()
        updateLastAssistant({
          content: 'Session expired. Please log in again.',
        })
        streamFinished = true
        return
      }

      if (!response.ok) throw new Error('Stream connection failed')

      const reader = response.body?.getReader()
      if (!reader) throw new Error('No reader')

      const decoder = new TextDecoder()
      let buffer = ''

      const processDataLine = (line: string) => {
        if (!line.startsWith('data: ')) return

        try {
          const data = JSON.parse(line.slice(6))

          // Handle done event — persist conversation_id
          if (data.type === 'done' && data.conversation_id) {
            localStorage.setItem('currentConversationId', String(data.conversation_id))
            upsertConversationSnapshot(String(data.conversation_id))
          }

          // Handle title event — update sidebar in real time
          if (data.type === 'title' && data.conversation_id && data.title) {
            useChatStore.getState().updateConversationTitle(
              String(data.conversation_id), data.title
            )
            upsertConversationSnapshot(String(data.conversation_id), data.title)
          }

          // Handle published event — report auto-published to wiki
          if (data.type === 'published') {
            useChatStore.setState({ lastPublishedFile: {
              file_id: data.file_id,
              filename: data.filename,
              wiki_url: data.wiki_url,
            }})
          }

          handleSSEEvent(data)
          if (data.type === 'done' || data.type === 'error') {
            streamFinished = true
          }
        } catch {
          // Partial chunk or incomplete JSON — append as raw text
          const text = line.slice(6)
          if (text.trim() && !text.trim().startsWith('{')) {
            const store = useChatStore.getState()
            const msgs = store.messages
            if (msgs.length > 0) {
              store.updateLastAssistant({
                content: (msgs[msgs.length - 1]?.content || '') + text,
              })
            }
          }
        }
      }

      while (true) {
        const { done, value } = await reader.read()
        if (done) {
          buffer += decoder.decode()
          break
        }

        buffer += decoder.decode(value, { stream: true })
        const lines = buffer.split('\n')
        buffer = lines.pop() || ''

        for (const line of lines) {
          processDataLine(line)
        }

      }

      if (!streamFinished && buffer.trim()) {
        for (const line of buffer.split('\n')) {
          processDataLine(line.trimEnd())
        }
      }
    } catch (err) {
      updateLastAssistant({
        content: `Error: ${err instanceof Error ? err.message : 'Connection failed'}`,
      })
    } finally {
      const currentConversationId = useChatStore.getState().currentId
      if (currentConversationId) {
        useChatStore.getState().upsertConversationSnapshot(currentConversationId)
      }
      setStreaming(false)
      // Refresh sidebar summaries after streaming completes, but avoid
      // replacing the current message list with a full conversation reload.
      try {
        if (!initialConversationId && streamFinished) {
          await new Promise((resolve) => setTimeout(resolve, 300))
          await useChatStore.getState().syncConversations()
        }
      } catch (err) {
        if (isUnauthorizedError(err)) {
          useAuthStore.getState().logout()
        }
        // Silently ignore refresh errors
      }
    }
  }

  return { sendMessage }
}

interface SSEEvent {
  type: 'text' | 'tool_call' | 'tool_update' | 'thinking' | 'state' | 'done' | 'error' | 'title' | 'published'
  content?: string
  stage?: string
  plan?: Array<{
    id: number
    tool_name: string
    description: string
    params?: Record<string, unknown>
    status: string
  }>
  current_step?: number
  step_results?: Array<{
    step: number
    tool: string
    status: string
    result_preview?: string
    error?: string
    duration?: number
  }>
  research_notes?: string
  waiting_for?: string | null
  tool_call?: { id: string; name: string }
  tool_update?: { id: string; status: string; duration?: number; error?: string }
  thinking?: string
  conversation_id?: string
  // Published event fields
  file_id?: string
  filename?: string
  wiki_url?: string
}

function handleSSEEvent(data: SSEEvent) {
  const store = useChatStore.getState()

  switch (data.type) {
    case 'state': {
      // Full agent state snapshot (VenusFactory2 pattern)
      setAgentState({
        stage: (data.stage as AgentState['stage']) || 'router',
        plan: (data.plan || []).map((p) => ({
          id: p.id,
          tool_name: p.tool_name,
          description: p.description,
          params: p.params,
          status: p.status as AgentState['plan'][0]['status'],
        })),
        current_step: data.current_step || 0,
        step_results: data.step_results || [],
        research_notes: data.research_notes || '',
        waiting_for: data.waiting_for || null,
      })

      // Sync tool calls from plan steps so ToolCallCard shows in the chat
      if (data.plan && data.plan.length > 0) {
        const msgs = store.messages
        const last = msgs[msgs.length - 1]
        if (last && last.role === 'assistant') {
          const existing = last.toolCalls || []
          // Build a map of existing tool calls by id
          const byId = new Map(existing.map((tc) => [tc.id, tc]))

          for (const step of data.plan) {
            const tcId = `plan-${step.id}`
            const existingTc = byId.get(tcId)

            if (existingTc) {
              // Update if status changed
              if (existingTc.status !== step.status) {
                store.updateToolCall(tcId, {
                  status: step.status as ToolCall['status'],
                })
              }
            } else if (step.status !== 'pending') {
              // Create new tool call for this plan step
              store.addToolCall({
                id: tcId,
                name: step.tool_name,
                status: step.status as ToolCall['status'],
              })
            }
          }
        }
      }

      // Link step_results to tool calls for result preview / PDB visualization
      if (data.step_results) {
        const msgs = store.messages
        const last = msgs[msgs.length - 1]
        if (last?.toolCalls) {
          for (const sr of data.step_results) {
            // Use step number to find matching tool call by plan index
            const planStep = data.plan?.find((p) => p.id === sr.step)
            const tcId = `plan-${sr.step}`
            const match = last.toolCalls.find(
              (tc) => tc.id === tcId && tc.status === 'completed' && !tc.resultPreview
            )
            if (match && sr.result_preview) {
              store.updateToolCall(tcId, { resultPreview: sr.result_preview })
            }
          }
        }
      }
      break
    }

    case 'text':
      {
        const lastMsg = store.messages[store.messages.length - 1]
        store.updateLastAssistant({
          content: (lastMsg?.content || '') + (data.content || ''),
        })
      }
      break

    case 'tool_call':
      if (data.tool_call) {
        store.addToolCall({
          id: data.tool_call.id,
          name: data.tool_call.name,
          status: 'pending',
        })
      }
      break

    case 'tool_update':
      if (data.tool_update) {
        store.updateToolCall(data.tool_update.id, {
          status: data.tool_update.status as 'running' | 'completed' | 'failed',
          duration: data.tool_update.duration,
          error: data.tool_update.error,
        })
      }
      break

    case 'thinking':
      if (data.thinking) {
        store.updateLastAssistant({
          thinking: [
            ...(store.messages[store.messages.length - 1]?.thinking || []),
            data.thinking,
          ],
        })
      }
      break

    case 'done':
      // Streaming completed — conversation_id is handled in sendMessage loop
      break

    case 'error':
      store.updateLastAssistant({
        content: (store.messages[store.messages.length - 1]?.content || '') +
          `\n\n❌ ${data.content || 'An error occurred'}`,
      })
      break
  }
}

function setAgentState(state: AgentState) {
  useChatStore.getState().setAgentState(state)
}

import { useCallback, useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { Activity, AlertTriangle, Building2, Database, Download, KeyRound, Loader2, ShieldCheck, UserCog, Users } from 'lucide-react'
import { api, ApiError, type AdminTaskAuditFilters, type AdminUser, type DeployDataImportRequest, type DeployDataReadiness, type Organization, type PermissionAudit, type ToolTaskAudit, type ToolTaskAuditSummary } from '@/lib/api'
import { useAuthStore } from '@/stores/auth'

type LoadState = 'idle' | 'loading' | 'ready' | 'error'

function formatTime(value?: string | null) {
  if (!value) return '—'
  try {
    return new Date(value).toLocaleString()
  } catch {
    return value
  }
}

function roleLabel(role: string) {
  return role === 'admin' ? '管理员' : '研发用户'
}

function formatBytes(value?: number | null) {
  if (!value) return '0 B'
  if (value < 1024) return `${value} B`
  if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`
  if (value < 1024 * 1024 * 1024) return `${(value / 1024 / 1024).toFixed(1)} MB`
  return `${(value / 1024 / 1024 / 1024).toFixed(1)} GB`
}

function statusClass(status: string) {
  if (status === 'ready') return 'bg-emerald-100 text-emerald-700'
  if (status === 'demo') return 'bg-amber-100 text-amber-700'
  if (status === 'empty') return 'bg-slate-100 text-slate-600'
  return 'bg-red-100 text-red-700'
}

function formatDuration(seconds?: number | null) {
  if (seconds == null) return '—'
  if (seconds < 60) return `${seconds}s`
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ${seconds % 60}s`
  return `${Math.floor(seconds / 3600)}h ${Math.floor((seconds % 3600) / 60)}m`
}

function cleanAuditFilters(filters: AdminTaskAuditFilters): AdminTaskAuditFilters {
  return Object.fromEntries(
    Object.entries(filters).filter(([, value]) => value !== undefined && value !== '' && value !== false)
  ) as AdminTaskAuditFilters
}

export function AdminPage() {
  const currentUser = useAuthStore((state) => state.user)
  const [users, setUsers] = useState<AdminUser[]>([])
  const [audits, setAudits] = useState<ToolTaskAudit[]>([])
  const [auditSummary, setAuditSummary] = useState<ToolTaskAuditSummary | null>(null)
  const [organizations, setOrganizations] = useState<Organization[]>([])
  const [permissionAudits, setPermissionAudits] = useState<PermissionAudit[]>([])
  const [dataReadiness, setDataReadiness] = useState<DeployDataReadiness | null>(null)
  const [dataUpdateFilters, setDataUpdateFilters] = useState<{ component?: string; status?: string }>({})
  const [filteredUpdates, setFilteredUpdates] = useState<DeployDataReadiness['updates']['manifests']>([])
  const [deployImport, setDeployImport] = useState<DeployDataImportRequest>({ symlink: true, dry_run: true })
  const [deployImportPlan, setDeployImportPlan] = useState<Record<string, unknown> | null>(null)
  const [state, setState] = useState<LoadState>('idle')
  const [message, setMessage] = useState<string | null>(null)
  const [auditFilters, setAuditFilters] = useState<AdminTaskAuditFilters>({})
  const [newOrgName, setNewOrgName] = useState('')
  const [orgMemberDrafts, setOrgMemberDrafts] = useState<Record<string, { email: string; role: 'member' | 'admin' }>>({})
  const [grantDrafts, setGrantDrafts] = useState<Record<string, { projectId: string; role: 'viewer' | 'editor' }>>({})

  const isAdmin = currentUser?.role === 'admin'

  const load = useCallback(async () => {
    if (!isAdmin) return
    setState('loading')
    setMessage(null)
    try {
      const [userResult, auditResult, readinessResult, organizationResult, permissionAuditResult] = await Promise.all([
        api.listAdminUsers(),
        api.listAdminTaskAudits(50, cleanAuditFilters(auditFilters)),
        api.getAdminDataReadiness(),
        api.listAdminOrganizations(),
        api.listAdminPermissionAudits(80),
      ])
      setUsers(userResult.users)
      setAudits(auditResult.audits)
      setAuditSummary(auditResult.summary || null)
      setDataReadiness(readinessResult)
      setFilteredUpdates(readinessResult.updates.manifests.filter((item) => item.exists))
      setOrganizations(organizationResult.organizations)
      setPermissionAudits(permissionAuditResult.audits)
      setState('ready')
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '加载管理数据失败'
      setMessage(detail)
      setState('error')
    }
  }, [isAdmin, auditFilters])

  useEffect(() => {
    void load()
  }, [load])

  const updateRole = async (user: AdminUser, role: 'admin' | 'researcher') => {
    setMessage(null)
    try {
      const updated = await api.updateAdminUserRole(user.id, role)
      setUsers((items) => items.map((item) => item.id === updated.id ? updated : item))
      setMessage(`${updated.email} 已更新为${roleLabel(updated.role)}`)
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '角色更新失败'
      setMessage(detail)
    }
  }

  const updateUserStatus = async (
    user: AdminUser,
    payload: { is_active?: boolean; locked?: boolean; disabled_reason?: string | null },
  ) => {
    setMessage(null)
    try {
      const updated = await api.updateAdminUserStatus(user.id, payload)
      setUsers((items) => items.map((item) => item.id === updated.id ? updated : item))
      setMessage(`${updated.email} 状态已更新`)
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '用户状态更新失败'
      setMessage(detail)
    }
  }

  const reloadOrganizations = async () => {
    const [organizationResult, permissionAuditResult] = await Promise.all([
      api.listAdminOrganizations(),
      api.listAdminPermissionAudits(80),
    ])
    setOrganizations(organizationResult.organizations)
    setPermissionAudits(permissionAuditResult.audits)
  }

  const createOrganization = async () => {
    const name = newOrgName.trim()
    if (!name) return
    setMessage(null)
    try {
      await api.createAdminOrganization(name)
      setNewOrgName('')
      await reloadOrganizations()
      setMessage(`组织 ${name} 已创建`)
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '组织创建失败'
      setMessage(detail)
    }
  }

  const updateOrgMemberDraft = (organizationId: string, patch: Partial<{ email: string; role: 'member' | 'admin' }>) => {
    setOrgMemberDrafts((drafts) => ({
      ...drafts,
      [organizationId]: {
        email: drafts[organizationId]?.email || '',
        role: drafts[organizationId]?.role || 'member',
        ...patch,
      },
    }))
  }

  const addOrganizationMember = async (organizationId: string) => {
    const draft = orgMemberDrafts[organizationId] || { email: '', role: 'member' as const }
    if (!draft.email.trim()) return
    setMessage(null)
    try {
      await api.addAdminOrganizationMember(organizationId, draft.email.trim(), draft.role)
      setOrgMemberDrafts((drafts) => ({ ...drafts, [organizationId]: { email: '', role: draft.role } }))
      await reloadOrganizations()
      setMessage('组织成员已更新')
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '组织成员更新失败'
      setMessage(detail)
    }
  }

  const updateOrganizationMember = async (organizationId: string, memberId: string, role: 'member' | 'admin') => {
    setMessage(null)
    try {
      await api.updateAdminOrganizationMember(organizationId, memberId, role)
      await reloadOrganizations()
      setMessage('组织成员角色已更新')
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '组织成员角色更新失败'
      setMessage(detail)
    }
  }

  const removeOrganizationMember = async (organizationId: string, memberId: string) => {
    setMessage(null)
    try {
      await api.removeAdminOrganizationMember(organizationId, memberId)
      await reloadOrganizations()
      setMessage('组织成员已移除')
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '组织成员移除失败'
      setMessage(detail)
    }
  }

  const updateGrantDraft = (organizationId: string, patch: Partial<{ projectId: string; role: 'viewer' | 'editor' }>) => {
    setGrantDrafts((drafts) => ({
      ...drafts,
      [organizationId]: {
        projectId: drafts[organizationId]?.projectId || '',
        role: drafts[organizationId]?.role || 'viewer',
        ...patch,
      },
    }))
  }

  const addProjectOrganizationGrant = async (organizationId: string) => {
    const draft = grantDrafts[organizationId] || { projectId: '', role: 'viewer' as const }
    if (!draft.projectId.trim()) return
    setMessage(null)
    try {
      await api.addProjectOrganizationGrant(draft.projectId.trim(), organizationId, draft.role)
      setGrantDrafts((drafts) => ({ ...drafts, [organizationId]: { projectId: '', role: draft.role } }))
      await reloadOrganizations()
      setMessage('项目组织授权已更新')
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '项目组织授权失败；需要管理员权限或项目 owner 权限'
      setMessage(detail)
    }
  }

  const updateProjectOrganizationGrant = async (projectId: string, grantId: string, role: 'viewer' | 'editor') => {
    setMessage(null)
    try {
      await api.updateProjectOrganizationGrant(projectId, grantId, role)
      await reloadOrganizations()
      setMessage('项目组织授权角色已更新')
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '项目组织授权角色更新失败'
      setMessage(detail)
    }
  }

  const removeProjectOrganizationGrant = async (projectId: string, grantId: string) => {
    setMessage(null)
    try {
      await api.removeProjectOrganizationGrant(projectId, grantId)
      await reloadOrganizations()
      setMessage('项目组织授权已撤销')
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '项目组织授权撤销失败'
      setMessage(detail)
    }
  }

  const exportAudits = async () => {
    setMessage(null)
    try {
      const response = await api.exportAdminTaskAudits(500, cleanAuditFilters(auditFilters))
      const blob = await response.blob()
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = 'tool-task-audits.csv'
      document.body.appendChild(link)
      link.click()
      link.remove()
      URL.revokeObjectURL(url)
      setMessage('任务审计 CSV 已开始下载')
    } catch (error) {
      const detail = error instanceof ApiError ? error.message : '审计导出失败'
      setMessage(detail)
    }
