      <div className="grid gap-5 xl:grid-cols-2">
        <LipasePaperListCard papers={data.results.papers || []} onSelectPaper={onSelectPaper} detailLoadingKey={detailLoadingKey} />
        <LipaseVariantListCard variants={data.results.variants || []} />
