                }}
                className="text-sm text-muted-foreground hover:text-foreground transition-colors"
              >
                Analyze another
              </button>
            </div>

            <PDBAnalysisCard
              data={{ ...analysis, lipaseEvidenceContext: lipaseEvidenceContext || analysis.lipaseEvidenceContext || undefined }}
              pdbContent={pdbContent ?? undefined}
              highlightResidues={structureHighlights}
              highlightRanges={structureHighlightRanges}
              highlightSummary={structureHighlightSummary}
            />

            {/* Quick actions */}
            <div className="overflow-hidden rounded-[28px] border border-border/70 bg-[radial-gradient(circle_at_top_left,rgba(59,130,246,0.08),transparent_26%),linear-gradient(180deg,rgba(255,255,255,0.96),rgba(248,250,252,0.98))] p-4 shadow-[0_24px_80px_-60px_rgba(15,23,42,0.45)] dark:bg-[radial-gradient(circle_at_top_left,rgba(59,130,246,0.16),transparent_30%),linear-gradient(180deg,rgba(15,23,42,0.96),rgba(2,6,23,0.98))] sm:p-5">
              <div className="flex flex-col gap-2 border-b border-border/60 pb-4 sm:flex-row sm:items-end sm:justify-between">
                <div>
                  <div className="text-[11px] font-semibold uppercase tracking-[0.24em] text-muted-foreground">
                    Structure Workflows
                  </div>
                  <h2 className="mt-2 text-xl font-semibold tracking-tight text-foreground">
                    Pick the next action for this structure
                  </h2>
                </div>
                <div className="flex flex-col gap-2 sm:min-w-[280px]">
                  <label className="text-[11px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">
                    MD Protocol
                  </label>
                  <select
                    value={selectedMdProtocolId}
                    onChange={(event) => setSelectedMdProtocolId(event.target.value)}
                    disabled={mdActionBusy || mdProtocols.length === 0}
                    className="rounded-xl border border-border bg-background px-3 py-2 text-sm text-foreground shadow-sm outline-none transition-colors focus:border-primary disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    {mdProtocols.length === 0 ? (
                      <option value={selectedMdProtocolId}>Loading protocols...</option>
                    ) : mdProtocols.map((protocol) => (
                      <option key={protocol.id} value={protocol.id}>{protocol.label}</option>
                    ))}
                  </select>
                  {selectedMdProtocol && (
                    <div className="space-y-1 text-xs leading-5 text-muted-foreground">
                      <div>
                        {selectedMdProtocol.parameters.simulation_time_ns} ns · {selectedMdProtocol.parameters.ensemble} · {selectedMdProtocol.parameters.force_field}
                      </div>
                      <div>
                        {selectedMdProtocol.risk_level}
                        {selectedMdProtocol.scientific_controls?.replicate_policy?.minimum_for_ranking
                          ? ` · ranking requires ${selectedMdProtocol.scientific_controls.replicate_policy.minimum_for_ranking} replicates`
                          : ''}
                      </div>
                    </div>
                  )}
                  {mdProtocolError && <div className="text-xs text-red-500">{mdProtocolError}</div>}
                </div>
              </div>

              <div className="mt-4 grid gap-3 md:grid-cols-2">
                {quickActions.map((action) => (
                  <button
                    key={action.key}
                    onClick={action.onClick}
                    disabled={action.disabled}
                    className={[
                      'group relative overflow-hidden rounded-[24px] border p-5 text-left transition-all duration-200',
                      'focus:outline-none focus:ring-2 focus:ring-primary/30',
                      'disabled:cursor-not-allowed disabled:opacity-65 disabled:hover:translate-y-0 disabled:hover:shadow-none',
                      action.primary ? 'min-h-[180px] md:col-span-2' : 'min-h-[170px]',
                      action.className,
                    ].join(' ')}
                  >
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_top_right,rgba(255,255,255,0.18),transparent_34%)] opacity-90" />
                    <div className="relative flex h-full flex-col">
                      <div className="flex items-start justify-between gap-3">
                        <div className={`inline-flex h-11 w-11 items-center justify-center rounded-2xl ${action.iconClassName}`}>
                          {action.loading ? <Loader2 className="h-5 w-5 animate-spin" /> : <ArrowRight className="h-5 w-5" />}
                        </div>
                        <span className={`inline-flex items-center rounded-full px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] ${action.badgeClassName}`}>
                          {action.badge}
                        </span>
                      </div>

                      <div className="mt-auto pt-8">
                        <div className={`text-xl font-semibold tracking-tight ${action.titleClassName}`}>
                          {action.title}
                        </div>
                        <p className={`mt-2 max-w-[34rem] text-sm leading-6 ${action.subtitleClassName}`}>
                          {action.subtitle}
                        </p>
                      </div>
                    </div>
                  </button>
                ))}
              </div>

              <div className="mt-4 rounded-2xl border border-teal-200/80 bg-white/75 px-4 py-3 text-sm dark:border-teal-900/60 dark:bg-slate-950/40">
                <label className="flex items-start gap-3">
                  <input
                    type="checkbox"
                    checked={lipaseNumberingConfirmed}
                    onChange={(event) => {
                      setLipaseNumberingConfirmed(event.target.checked)
                      setLipaseError(null)
                      if (!event.target.checked) setLipaseEvidenceContext(null)
                    }}
                    className="mt-1 h-4 w-4 rounded border-teal-300 text-teal-600 focus:ring-teal-500"
                    disabled={!isStructureMappingResult(mappingResult)}
                  />
                  <span>
                    <span className="block font-medium text-slate-900 dark:text-slate-50">
                      KWB lipase numbering confirmed
                    </span>
                    <span className="mt-1 block text-xs leading-5 text-slate-500 dark:text-slate-400">
                      Enables lipase evidence overlay only after residue mapping is available and the sequence numbering relationship has been checked.
                    </span>
                  </span>
                </label>
                {lipaseError ? (
                  <div className="mt-3 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-600 dark:border-red-900/60 dark:bg-red-950/30 dark:text-red-300">
                    {lipaseError}
                  </div>
                ) : null}
              </div>

              {mdTaskId && (
                <div className="mt-4 flex justify-end">
                  <button
                    onClick={() => { void cancelMdValidation() }}
                    className="inline-flex items-center gap-2 rounded-full border border-red-200 bg-white/80 px-4 py-2 text-sm font-medium text-red-600 transition-colors hover:bg-red-50 dark:border-red-900/60 dark:bg-red-950/20 dark:text-red-300 dark:hover:bg-red-950/40"
                    disabled={mdCanceling}
                  >
                    {mdCanceling ? <Loader2 className="w-4 h-4 animate-spin" /> : <AlertCircle className="w-4 h-4" />}
                    {mdCanceling ? 'Canceling...' : 'Cancel MD Run'}
                  </button>
                </div>
              )}
            </div>

            {(mdStatus || mdError || displayedMdTaskId) && (
              <div className="rounded-xl border border-border bg-card p-4 text-sm">
                <div className="font-medium text-foreground">MD Task Status</div>
                <div className="mt-2 text-muted-foreground">
                  {displayedMdTaskId ? `${mdTaskId ? 'Active task' : 'Last task'} ${displayedMdTaskId}` : 'No task submitted'}
                </div>
                {mdStatus && (
                  <div className={`mt-2 font-medium ${mdStatusTone(mdStatus)}`}>
                    {formatMdStatus(mdStatus)}
                  </div>
                )}
                {mdStageMessage && (
                  <div className="mt-2 text-sm text-foreground">
                    {mdStageMessage}
                    {mdStepLabel ? <span className="ml-2 text-muted-foreground">Step {mdStepLabel}</span> : null}
                  </div>
                )}
                {typeof mdProgress === 'number' && (
                  <div className="mt-3">
                    <div className="flex items-center justify-between text-xs text-muted-foreground">
                      <span>Worker progress</span>
                      <span>{mdProgress}%</span>
                    </div>
                    <div className="mt-1 h-2 overflow-hidden rounded-full bg-secondary">
                      <div
                        className="h-full rounded-full bg-blue-500 transition-all duration-500"
                        style={{ width: `${mdProgress}%` }}
                      />
                    </div>
                  </div>
                )}
                {mdTaskId && !mdCancelRequestedAt && (
                  <div className="mt-2 text-xs text-muted-foreground">
                    Polling worker status every 3 seconds.
                  </div>
                )}
                {mdCancelRequestedAt && (
                  <div className="mt-2 text-amber-600 dark:text-amber-300">
                    Cancel requested at {new Date(mdCancelRequestedAt).toLocaleString()}. Waiting for worker terminal state.
                  </div>
                )}
                {mdError && <div className="mt-2 text-red-500">{mdError}</div>}
              </div>
            )}

            {isMDResult(mdResult) && (
              <MDResultView data={mdResult} taskId={mdLastTaskId} />
            )}

            <LigandPreflightCard result={ligandResult} error={ligandError} />

            {mappingError && (
              <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-600 dark:border-red-900/60 dark:bg-red-950/30 dark:text-red-300">
                {mappingError}
              </div>
            )}

            {isStructureMappingResult(mappingResult) && (
              <StructureMappingCard data={mappingResult} />
            )}

            {searchError && (
              <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-600 dark:border-red-900/60 dark:bg-red-950/30 dark:text-red-300">
                {searchError}
              </div>
            )}

            {isStructureSearchResult(searchResult) && (
              <StructureSearchResultCard data={searchResult} />
            )}

            {annotationError && (
              <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-600 dark:border-red-900/60 dark:bg-red-950/30 dark:text-red-300">
                {annotationError}
              </div>
            )}

            {isAnnotationBundleResult(annotationResult) && (
              <AnnotationBundleCard data={annotationResult} />
            )}
          </div>
        )}
      </div>
    </div>
  )
}

import { useEffect, useState, useMemo } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Plus, Trash2, Play, Loader2, CheckCircle2, XCircle, Dna, Beaker, Zap, History, BookOpen, FileText, ChevronDown, ChevronRight } from 'lucide-react'
import { api, type ProjectAccessRole, type ProjectPermissions } from '@/lib/api'
import { MarkdownView } from '@/components/chat/MarkdownView'

interface SeqItem { id: string; name: string; sequence: string; notes?: string | null; created_at: string }
interface BatchItem { id: string; status: string; total: number; completed: number; results?: any; created_at: string }
interface ProjectData { id: string; name: string; description?: string | null; access_role: ProjectAccessRole; permissions?: ProjectPermissions; sequences: SeqItem[]; batch_jobs: BatchItem[] }
interface WikiFile { id: string; filename: string; sequence_name: string; file_type: string; object_name: string; size: number; created_at: string }
interface WikiGroup { tool: string; job_id: string; files: WikiFile[] }
interface WikiCollection { name: string; groups: WikiGroup[] }

const BATCH_TOOLS = [
  { id: 'protein_benchmark', label: 'Benchmark', icon: Beaker },
  { id: 'mutation_priority_score', label: 'Mutation Score', icon: Zap },
  { id: 'predict_properties', label: 'Properties', icon: Dna },
]

export function ProjectDetailPage() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const [project, setProject] = useState<ProjectData | null>(null)
  const [loading, setLoading] = useState(true)
  const [showAddSeq, setShowAddSeq] = useState(false)
  const [seqName, setSeqName] = useState('')
  const [seqData, setSeqData] = useState('')
  const [seqNotes, setSeqNotes] = useState('')
  const [adding, setAdding] = useState(false)
  const [running, setRunning] = useState(false)
  const [activeTab, setActiveTab] = useState<'sequences' | 'results' | 'wiki'>('sequences')
  const [selectedTool, setSelectedTool] = useState('protein_benchmark')
  const [wikiTree, setWikiTree] = useState<WikiCollection[]>([])
  const [selectedWikiFile, setSelectedWikiFile] = useState<{ projectId: string; fileId: string; filename: string } | null>(null)
  const [wikiContent, setWikiContent] = useState<string>('')
  const [wikiLoading, setWikiLoading] = useState(false)
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set())

  const fetchWikiTree = async () => {
    if (!id) return
    try {
      const files: any[] = await api.getProjectFiles(id)
      // Group files by source (batch, agent, upload) into WikiCollection structure
      const groupsBySource = new Map<string, WikiGroup>()
      for (const f of files) {
        const source = f.source || 'general'
        const job_id = f.tags?.batch_job_id || 'default'
        const key = `${source}:${job_id}`
        if (!groupsBySource.has(key)) {
          groupsBySource.set(key, { tool: source, job_id, files: [] })
        }
        groupsBySource.get(key)!.files.push(f as WikiFile)
      }
      const collections: WikiCollection[] = [{ name: '项目文件', groups: Array.from(groupsBySource.values()) }]
      setWikiTree(collections)
    } catch { /* ignore */ }
  }

  const handleViewWikiFile = async (projectId: string, fileId: string, filename: string) => {
    setSelectedWikiFile({ projectId, fileId, filename })
    setWikiLoading(true)
    try {
      const content = await api.getFileContent(projectId, fileId)
      setWikiContent(content)
    } catch {
      setWikiContent('Failed to load file content.')
    } finally {
      setWikiLoading(false)
    }
  }

  const toggleGroup = (key: string) => {
    setExpandedGroups(prev => {
      const next = new Set(prev)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  }

  const fetchProject = async () => {
    if (!id) return
    try {
      setLoading(true)
      const data = await api.getProject(id)
      setProject(data)
    } catch { navigate('/projects') } finally { setLoading(false) }
  }

  useEffect(() => {
    fetchProject()
    fetchWikiTree()
  }, [id])

  useEffect(() => {
    if (activeTab === 'wiki') fetchWikiTree()
  }, [activeTab])

  const handleAddSeq = async () => {
    if (!id || !seqName.trim() || !seqData.trim()) return
    setAdding(true)
    try {
      await api.addSequence(id, seqName.trim(), seqData.trim(), seqNotes.trim() || undefined)
      setShowAddSeq(false)
      setSeqName('')
      setSeqData('')
      setSeqNotes('')
      fetchProject()
    } catch { /* ignore */ } finally { setAdding(false) }
  }

  const handleRemoveSeq = async (seqId: string) => {
    if (!id) return
    try {
      await api.removeSequence(id, seqId)
      fetchProject()
    } catch { /* ignore */ }
  }

  const handleBatchRun = async () => {
    if (!id) return
    setRunning(true)
    try {
      await api.batchRun(id, selectedTool)
      fetchProject()
      fetchWikiTree()  // Refresh wiki after batch auto-publish
    } catch { /* ignore */ } finally { setRunning(false) }
  }

  const batchResults = useMemo(() => {
    if (!project?.batch_jobs?.length) return []
    return project.batch_jobs.flatMap((job) => {
      if (!job.results?.items) return []
      return job.results.items.map((item: any) => ({
        ...item,
        jobId: job.id,
        jobStatus: job.status,
        jobDate: job.created_at,
        tool: job.results?.tool,
      }))
    })
  }, [project?.batch_jobs])

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
      </div>
    )
  }

  if (!project) return null
  const canCreateSequence = project.permissions?.['project.sequence.create'] ?? (project.access_role === 'owner' || project.access_role === 'editor')
  const canDeleteSequence = project.permissions?.['project.sequence.delete'] ?? (project.access_role === 'owner' || project.access_role === 'editor')
  const canRunBatch = project.permissions?.['project.batch.run'] ?? (project.access_role === 'owner' || project.access_role === 'editor')

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 py-6 sm:py-10">
        {/* Header */}
        <div className="flex items-center gap-3 mb-1">
          <button onClick={() => navigate('/projects')} className="p-1.5 rounded-md hover:bg-secondary text-muted-foreground">
            <ArrowLeft className="w-5 h-5" />
          </button>
          <h1 className="text-xl font-bold">{project.name}</h1>
          <span className="rounded-full bg-secondary px-2 py-0.5 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
            {project.access_role}
          </span>
        </div>
        {project.description && (
          <p className="text-sm text-muted-foreground ml-11 mb-6">{project.description}</p>
        )}

        {/* Tabs */}
        <div className="flex items-center gap-1 bg-secondary rounded-lg p-0.5 w-fit mb-6">
          {[
            { key: 'sequences', label: `Sequences (${project.sequences.length})`, icon: Dna },
            { key: 'results', label: `Results (${batchResults.length})`, icon: History },
            { key: 'wiki', label: `Wiki (${wikiTree.reduce((acc, c) => acc + c.groups.length, 0)})`, icon: BookOpen },
          ].map((tab) => {
            const Icon = tab.icon
            return (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key as any)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
                  activeTab === tab.key ? 'bg-background text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                <Icon className="w-3.5 h-3.5" />
                {tab.label}
              </button>
            )
          })}
        </div>

        {/* Sequences Tab */}
        {activeTab === 'sequences' && (
          <div>
            {/* Add button */}
            <div className="flex items-center justify-between mb-4">
              <p className="text-sm text-muted-foreground">
                Manage protein sequences for batch analysis
              </p>
              {canCreateSequence && (
                <button
                  onClick={() => setShowAddSeq(true)}
                  className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-primary text-primary-foreground text-xs font-medium hover:bg-primary/90"
                >
                  <Plus className="w-3.5 h-3.5" />
                  Add Sequence
                </button>
              )}
            </div>

            {/* Add sequence form */}
            {canCreateSequence && showAddSeq && (
              <div className="bg-card border border-border rounded-xl p-4 mb-4 space-y-3">
                <input
                  autoFocus
                  value={seqName}
                  onChange={(e) => setSeqName(e.target.value)}
                  placeholder="Sequence name (e.g. 'BLA-WT')"
                  className="w-full px-3 py-2 rounded-lg border border-border bg-transparent text-sm focus:outline-none focus:border-ring"
                />
                <textarea
                  value={seqData}
                  onChange={(e) => setSeqData(e.target.value.toUpperCase())}
                  placeholder="Amino acid sequence (single-letter code)"
                  rows={3}
                  className="w-full px-3 py-2 rounded-lg border border-border bg-transparent text-sm font-mono focus:outline-none focus:border-ring resize-none"
                />
                <input
                  value={seqNotes}
                  onChange={(e) => setSeqNotes(e.target.value)}
                  placeholder="Notes (optional)"
                  className="w-full px-3 py-2 rounded-lg border border-border bg-transparent text-sm focus:outline-none focus:border-ring"
                />
                <div className="flex gap-2 justify-end">
                  <button onClick={() => setShowAddSeq(false)} className="px-3 py-1.5 text-xs text-muted-foreground hover:bg-secondary rounded-lg">Cancel</button>
                  <button onClick={handleAddSeq} disabled={!seqName.trim() || !seqData.trim() || adding} className="flex items-center gap-1.5 px-3 py-1.5 bg-primary text-primary-foreground text-xs font-medium rounded-lg disabled:opacity-40">
                    {adding && <Loader2 className="w-3 h-3 animate-spin" />}
                    Add
                  </button>
                </div>
              </div>
            )}

            {/* Sequence list */}
            {project.sequences.length === 0 ? (
              <div className="text-center py-16 bg-card border border-border rounded-xl">
                <Dna className="w-12 h-12 text-muted-foreground/30 mx-auto mb-4" />
                <p className="text-muted-foreground">No sequences in this project</p>
                <p className="text-sm text-muted-foreground/70 mt-1">Add sequences to start batch analysis</p>
              </div>
            ) : (
              <div className="space-y-2">
                {project.sequences.map((seq) => (
                  <div key={seq.id} className="group flex items-start gap-4 bg-card border border-border rounded-xl p-4">
                    <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center shrink-0 mt-0.5">
                      <Dna className="w-4 h-4 text-primary" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h4 className="text-sm font-medium">{seq.name}</h4>
                      <code className="text-xs text-muted-foreground break-all font-mono mt-1 block">{seq.sequence.length > 80 ? seq.sequence.slice(0, 80) + '...' : seq.sequence}</code>
                      {seq.notes && <p className="text-[10px] text-muted-foreground mt-1">{seq.notes}</p>}
                    </div>
                    {canDeleteSequence && (
                      <button
                        onClick={() => handleRemoveSeq(seq.id)}
                        className="p-1.5 rounded-md hover:bg-red-500/10 text-muted-foreground hover:text-red-400 opacity-0 group-hover:opacity-100 transition-all shrink-0"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </div>
                ))}
              </div>
            )}

            {/* Batch Run Panel */}
            {canRunBatch && project.sequences.length > 0 && (
              <div className="mt-6 bg-card border border-border rounded-xl p-4">
                <h3 className="font-semibold text-sm mb-3">Batch Analysis</h3>
                <div className="flex flex-wrap items-end gap-3">
                  <div>
                    <label className="text-[10px] text-muted-foreground block mb-1">Tool</label>
                    <div className="flex gap-1">
                      {BATCH_TOOLS.map((tool) => {
                        const Icon = tool.icon
                        return (
                          <button
                            key={tool.id}
                            onClick={() => setSelectedTool(tool.id)}
                            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                              selectedTool === tool.id ? 'bg-primary text-primary-foreground' : 'bg-secondary text-muted-foreground hover:text-foreground'
                            }`}
                          >
                            <Icon className="w-3 h-3" />
                            {tool.label}
                          </button>
                        )
                      })}
                    </div>
                  </div>
                  <button
                    onClick={handleBatchRun}
                    disabled={running}
                    className="flex items-center gap-2 px-4 py-1.5 rounded-lg bg-emerald-500 text-white text-xs font-medium hover:bg-emerald-600 disabled:opacity-40"
                  >
                    {running ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Play className="w-3.5 h-3.5" />}
                    {running ? 'Running...' : `Run on ${project.sequences.length} sequences`}
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Results Tab */}
        {activeTab === 'results' && (
          <div>
            {batchResults.length === 0 ? (
              <div className="text-center py-16 bg-card border border-border rounded-xl">
                <History className="w-12 h-12 text-muted-foreground/30 mx-auto mb-4" />
                <p className="text-muted-foreground">No analysis results yet</p>
                <p className="text-sm text-muted-foreground/70 mt-1">Run a batch analysis on your sequences</p>
              </div>
            ) : (
              <div className="space-y-2">
                {batchResults.map((r: any, i: number) => (
                  <div key={i} className="flex items-start gap-3 bg-card border border-border rounded-xl p-4">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${r.status === 'completed' ? 'bg-emerald-500/10' : 'bg-red-500/10'}`}>
                      {r.status === 'completed' ? (
                        <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                      ) : (
                        <XCircle className="w-4 h-4 text-red-400" />
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-0.5">
                        <span className="font-medium text-sm">{r.sequence_name}</span>
                        <span className="text-[10px] text-muted-foreground px-1.5 py-0.5 bg-secondary rounded">{r.tool}</span>
                      </div>
                      {r.status === 'completed' && r.result && (
                        <details className="mt-1">
