  }

  await page.screenshot({ path: '/tmp/wiki-final-v2.png', fullPage: true });

  if (hasRendered && hasDashboard && !hasLogin) {
    console.log('\n✅ SUCCESS: Outline fully loaded with SSO in iframe');
